def widestFenceArea(heights: list[int]) -> int:
    left = 0
    right = len(heights) - 1
    max_area = 0
    while left < right:
        h = min(heights[left], heights[right])
        max_area = max(max_area, h * (right - left))
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
    return max_area

#include <vector>
#include <algorithm>

class Solution {
public:
    long long widestFenceArea(std::vector<int>& heights) {
        int left = 0, right = (int)heights.size() - 1;
        long long maxArea = 0;
        while (left < right) {
            long long h = std::min(heights[left], heights[right]);
            maxArea = std::max(maxArea, h * (right - left));
            if (heights[left] < heights[right]) left++;
            else right--;
        }
        return maxArea;
    }
};

